def _require_secret(name: str, help_text: str = "") -> str:
    value = st.secrets.get(name, "")
    if not value:
        st.error(
            f"Configuration manquante : `{name}` n'est pas défini dans les secrets Streamlit. "
            + help_text
        )
        st.stop()
    return value


