# ============================================================
# CLIENT SUPABASE — APPELS REST DIRECTS
# ============================================================
# La librairie supabase-py utilise httpx en mode asynchrone en interne.
# Dans le thread d'exécution spécifique à Streamlit, cette résolution DNS
# asynchrone peut échouer alors que des appels HTTP simples et synchrones
# fonctionnent parfaitement. Pour éviter ce problème, on parle directement
# à l'API REST de Supabase avec `requests` (fiable, synchrone, testé).

AUTH_URL = f"{SUPABASE_URL}/auth/v1"
REST_URL = f"{SUPABASE_URL}/rest/v1"


def _auth_headers(access_token: str | None = None) -> dict:
    headers = {
        "apikey": SUPABASE_KEY,
        "Content-Type": "application/json",
    }
    headers["Authorization"] = f"Bearer {access_token or SUPABASE_KEY}"
    return headers


# ============================================================
# RETOUR DE PAIEMENT STRIPE — VÉRIFICATION SERVEUR À SERVEUR
# ============================================================
# Après un paiement, la session Streamlit de l'utilisateur est perdue (il
# revient sur l'app via une redirection externe, la page se recharge à
# zéro). On ne peut donc pas se fier à "qui est connecté en ce moment" —
# on identifie le client par l'e-mail que STRIPE nous confirme avoir
# encaissé, après avoir vérifié le paiement directement auprès de Stripe
# (jamais en se fiant au seul paramètre d'URL, qui peut être falsifié
# par n'importe qui en tapant l'URL à la main).

def _service_role_headers() -> dict:
    return {
        "apikey": SUPABASE_SERVICE_ROLE_KEY,
        "Authorization": f"Bearer {SUPABASE_SERVICE_ROLE_KEY}",
        "Content-Type": "application/json",
    }


def verify_stripe_session(session_id: str) -> dict | None:
    """Interroge directement l'API Stripe pour confirmer qu'une session de
    paiement a réellement été payée. Retourne None si la clé secrète
    Stripe n'est pas configurée, si la session n'existe pas, ou si elle
    n'est pas payée — dans tous ces cas, on ne débloque rien."""
    if not STRIPE_SECRET_KEY:
        return None
    try:
        response = requests.get(
            f"https://api.stripe.com/v1/checkout/sessions/{session_id}",
            headers={"Authorization": f"Bearer {STRIPE_SECRET_KEY}"},
            timeout=10,
        )
        if response.status_code >= 400:
            return None
        data = response.json()
        if data.get("payment_status") != "paid":
            return None
        return data
    except Exception:
        return None


def add_credits_by_email(email: str, credits_to_add: int) -> bool:
    """Ajoute des crédits au profil correspondant à cet e-mail, via la clé
    service_role (contourne le RLS puisqu'on n'a plus la session de
    l'utilisateur à ce stade). La jauge d'affichage (credits_gauge_max) est
    remise au niveau du nouveau solde, pour que la pilule de crédits
    apparaisse pleine juste après l'achat. Retourne True si l'ajout a bien
    eu lieu."""
    if not SUPABASE_SERVICE_ROLE_KEY or credits_to_add <= 0:
        return False
    try:
        headers = _service_role_headers()
        response = requests.get(
            f"{REST_URL}/profiles",
            headers=headers,
            params={"email": f"eq.{email}", "select": "id,credits"},
            timeout=10,
        )
        rows = response.json() if response.status_code < 400 else []
        if not rows:
            return False
        new_balance = int(rows[0].get("credits") or 0) + credits_to_add
        headers["Prefer"] = "return=minimal"
        requests.patch(
            f"{REST_URL}/profiles",
            headers=headers,
            params={"id": f"eq.{rows[0]['id']}"},
            json={"credits": new_balance, "credits_gauge_max": new_balance},
            timeout=10,
        )
        return True
    except Exception:
        return False


def handle_stripe_return() -> None:
    """À appeler tôt dans main(). Vérifie si l'utilisateur revient d'un
    paiement Stripe réussi (paramètres d'URL) et, si le paiement est
    confirmé auprès de Stripe, crédite le pack correspondant."""
    params = st.query_params
    if params.get("payment") != "success":
        return
    session_id = params.get("session_id", "")
    pack_key = params.get("pack", "")
    pack = CREDIT_PACKS.get(pack_key)

    session_data = verify_stripe_session(session_id) if session_id else None
    if not session_data:
        st.error(
            "Paiement non confirmé par Stripe — si tu penses qu'il s'agit "
            "d'une erreur, contacte le support avec ta référence de paiement."
        )
        st.query_params.clear()
        return

    email = (session_data.get("customer_details") or {}).get("email", "")
    if email and pack and add_credits_by_email(email, pack["credits"]):
        st.markdown(
            f'<div class="mm-purchase-banner">⚡ Paiement validé ! '
            f'Vos {pack["credits"]} crédits ont été ajoutés à votre compte '
            f'({email}). Connecte-toi avec ce compte pour en profiter.</div>',
            unsafe_allow_html=True,
        )
    else:
        st.warning(
            "Paiement confirmé par Stripe, mais l'ajout automatique des crédits a "
            "échoué (compte introuvable ou configuration incomplète). Contacte le support."
        )
    st.query_params.clear()


# ============================================================
# AUTORISATION OAUTH ALIEXPRESS (API DROP SHIPPING)
# ============================================================
# Les méthodes "aliexpress.ds.*" (Drop Shipping) — contrairement à
# "aliexpress.affiliate.*" — exigent qu'un compte AliExpress autorise
# explicitement l'app une fois (flux OAuth2), ce qui produit un
# access_token à joindre à chaque appel signé. Ce jeton est stocké dans
# Supabase (table app_config, accessible uniquement via service_role),
# pas dans une session utilisateur : il est partagé par toute l'app.

ALIEXPRESS_OAUTH_AUTHORIZE_URL = "https://api-sg.aliexpress.com/oauth/authorize"
ALIEXPRESS_OAUTH_TOKEN_URL = "https://oauth.aliexpress.com/token"


def get_app_config(key: str) -> str | None:
    if not SUPABASE_SERVICE_ROLE_KEY:
        return None
    try:
        response = requests.get(
            f"{REST_URL}/app_config",
            headers=_service_role_headers(),
            params={"key": f"eq.{key}", "select": "value"},
            timeout=10,
        )
        rows = response.json() if response.status_code < 400 else []
        return rows[0]["value"] if rows else None
    except Exception:
        return None


def set_app_config(key: str, value: str) -> bool:
    if not SUPABASE_SERVICE_ROLE_KEY:
        return False
    try:
        headers = _service_role_headers()
        headers["Prefer"] = "resolution=merge-duplicates,return=minimal"
        response = requests.post(
            f"{REST_URL}/app_config",
            headers=headers,
            json={"key": key, "value": value, "updated_at": datetime.now(timezone.utc).isoformat()},
            timeout=10,
        )
        return response.status_code < 400
    except Exception:
        return False


def get_aliexpress_authorize_url() -> str:
    return (
        f"{ALIEXPRESS_OAUTH_AUTHORIZE_URL}?response_type=code&force_auth=true"
        f"&redirect_uri={requests.utils.quote(APP_BASE_URL, safe='')}"
        f"&client_id={ALIEXPRESS_APP_KEY}"
    )


def exchange_aliexpress_code_for_token(code: str) -> dict | None:
    try:
        response = requests.post(
            ALIEXPRESS_OAUTH_TOKEN_URL,
            data={
                "grant_type": "authorization_code",
                "client_id": ALIEXPRESS_APP_KEY,
                "client_secret": ALIEXPRESS_APP_SECRET,
                "code": code,
                "redirect_uri": APP_BASE_URL,
                "sp": "ae",
            },
            timeout=15,
        )
        data = response.json()
        if response.status_code >= 400 or "access_token" not in data:
            st.session_state["last_aliexpress_oauth_error"] = data
            return None
        return data
    except Exception as exc:
        st.session_state["last_aliexpress_oauth_error"] = f"{type(exc).__name__}: {exc}"
        return None


def handle_aliexpress_oauth_return() -> None:
    """À appeler tôt dans main(). Si AliExpress vient de rediriger avec un
    code d'autorisation, l'échange contre un jeton d'accès et le stocke."""
    code = st.query_params.get("code")
    if not code:
        return
    token_data = exchange_aliexpress_code_for_token(code)
    if token_data:
        set_app_config("aliexpress_access_token", token_data.get("access_token", ""))
        set_app_config("aliexpress_refresh_token", token_data.get("refresh_token", ""))
        st.success("Autorisation AliExpress réussie ! L'app peut maintenant chercher de vrais produits.")
    else:
        st.error(
            "Échec de l'autorisation AliExpress — vérifie le diagnostic admin "
            "pour le détail de l'erreur."
        )
    st.query_params.clear()


def supabase_sign_in(email: str, password: str) -> dict:
    """Retourne le JSON de réponse GoTrue, ou lève une exception avec le
    message d'erreur renvoyé par Supabase."""
    response = requests.post(
        f"{AUTH_URL}/token?grant_type=password",
        headers=_auth_headers(),
        json={"email": email, "password": password},
        timeout=10,
    )
    data = response.json()
    if response.status_code >= 400:
        raise RuntimeError(data.get("error_description") or data.get("msg") or "Échec de connexion")
    return data


def supabase_sign_up(email: str, password: str) -> dict:
    response = requests.post(
        f"{AUTH_URL}/signup",
        headers=_auth_headers(),
        json={"email": email, "password": password},
        timeout=10,
    )
    data = response.json()
    if response.status_code >= 400:
        raise RuntimeError(data.get("error_description") or data.get("msg") or "Échec d'inscription")
    return data


def supabase_request_password_reset(email: str) -> None:
    """Déclenche l'e-mail de réinitialisation de mot de passe GoTrue.
    L'endpoint /recover répond 200 que le compte existe ou non (anti
    énumération côté Supabase) — on ne remonte donc jamais d'erreur
    spécifique à l'utilisateur, juste un message générique. Les erreurs
    réseau sont avalées pour la même raison : le message affiché à
    l'utilisateur ne doit jamais dépendre du résultat réel de l'appel."""
    try:
        requests.post(
            f"{AUTH_URL}/recover",
            headers=_auth_headers(),
            json={"email": email},
            timeout=10,
        )
    except Exception:
        pass


def supabase_select_profile(user_id: str, access_token: str | None) -> dict | None:
    # La clé primaire de public.profiles est 'id' (= auth.users.id), pas
    # 'user_id' — voir schema_margemax.sql. Filtrer sur 'user_id' (colonne
    # inexistante sur cette table) faisait échouer CETTE requête à chaque
    # appel (400 de PostgREST), donc ne trouvait jamais le profil créé par
    # le trigger handle_new_user() — c'était la vraie cause du blocage à 0
    # crédit, bien plus que la seule colonne 'credits' manquante.
    response = requests.get(
        f"{REST_URL}/profiles",
        headers=_auth_headers(access_token),
        params={"id": f"eq.{user_id}", "select": "*"},
        timeout=10,
    )
    if response.status_code >= 400:
        return None
    rows = response.json()
    return rows[0] if rows else None


def supabase_insert_profile(profile: dict, access_token: str | None) -> None:
    headers = _auth_headers(access_token)
    headers["Prefer"] = "return=minimal"
    requests.post(f"{REST_URL}/profiles", headers=headers, json=profile, timeout=10)


def supabase_update_profile(user_id: str, patch: dict, access_token: str | None) -> None:
    headers = _auth_headers(access_token)
    headers["Prefer"] = "return=minimal"
    requests.patch(
        f"{REST_URL}/profiles",
        headers=headers,
        params={"id": f"eq.{user_id}"},
        json=patch,
        timeout=10,
    )


# ============================================================
# ÉTAT DE SESSION
# ============================================================

def init_session_state() -> None:
    defaults = {
        "user": None,
        "profile": None,
        "page": "recherche",
        "public_page": "accueil",
        "last_result": None,
        "auth_error": None,
        "remember_me": False,
    }
    for key, value in defaults.items():
        if key not in st.session_state:
            st.session_state[key] = value


def is_logged_in() -> bool:
    return st.session_state.get("user") is not None


def is_admin() -> bool:
    profile = st.session_state.get("profile")
    if not profile:
        return False
    if profile.get("is_admin") or profile.get("role") == "admin":
        return True
    user = st.session_state.get("user")
    return bool(user and user.get("email") == ADMIN_EMAIL)


def is_suspended() -> bool:
    profile = st.session_state.get("profile") or {}
    return bool(profile.get("is_suspended")) and not is_admin()


def get_credits_balance() -> int | float:
    """Solde de crédits prépayés de l'utilisateur courant. Illimité (∞)
    pour l'admin, qui n'est jamais débité."""
    if is_admin():
        return math.inf
    profile = st.session_state.get("profile") or {}
    return int(profile.get("credits") or 0)


def get_credits_gauge_max() -> int:
    """Référence d'affichage de la jauge de crédits — remise au niveau du
    solde à chaque ajout (inscription ou achat), pour que la pilule
    apparaisse pleine juste après un top-up puis se vide avec l'usage."""
    profile = st.session_state.get("profile") or {}
    return int(profile.get("credits_gauge_max") or FREE_SIGNUP_CREDITS)


def has_credits() -> bool:
    return is_admin() or get_credits_balance() > 0


def credits_pill_html() -> str:
    """Pilule de crédits (jauge néon violet/cyan) — même composant réutilisé
    en haut à droite de chaque page connectée."""
    if is_admin():
        return (
            '<div class="mm-credits-widget">'
            '<div class="mm-credits-pro"><span class="infinity">∞</span> Crédits illimités</div>'
            '</div>'
        )
    balance = get_credits_balance()
    gauge_max = get_credits_gauge_max()
    pct = min(100, round((balance / gauge_max) * 100)) if gauge_max else 0
    return (
        '<div class="mm-credits-widget">'
        f'<div class="mm-credits-label"><span>Crédits restants</span>'
        f'<strong>{balance} / {gauge_max}</strong></div>'
        '<div class="mm-credits-bar-track">'
        f'<div class="mm-credits-bar-fill" style="width:{pct}%;"></div></div>'
        '</div>'
    )


def render_page_header(title_html: str) -> None:
    """En-tête de page connectée : titre à gauche, pilule de crédits à
    droite (même schéma que le tableau de bord)."""
    st.markdown(
        f'<div class="mm-topbar mm-page-header">'
        f'<h2>{title_html}</h2>'
        f'{credits_pill_html()}'
        f'</div>',
        unsafe_allow_html=True,
    )


def debit_credit() -> None:
    """Débite 1 crédit après une action réussie (recherche, calcul de
    marge, génération de fiche produit). Aucun effet pour l'admin."""
    if is_admin():
        return
    profile = st.session_state.get("profile") or {}
    user = st.session_state.get("user")
    new_balance = max(0, int(profile.get("credits") or 0) - 1)
    profile["credits"] = new_balance
    st.session_state["profile"] = profile
    if user:
        try:
            supabase_update_profile(user["id"], {"credits": new_balance}, user.get("access_token"))
        except Exception:
            pass


def render_no_credits_alert() -> None:
    """Alerte moderne affichée à la place d'une action (recherche, calcul,
    fiche produit) quand le solde de crédits est épuisé."""
    st.markdown(
        """
        <div class="mm-credits-alert">
            <div class="icon">⚠️</div>
            <div class="title">Solde de crédits épuisé</div>
            <div class="subtitle">Achète un pack de crédits pour continuer à sourcer des produits,
            calculer tes marges et générer tes fiches produit.</div>
        </div>
        """,
        unsafe_allow_html=True,
    )
    if st.button("💳 Acheter des crédits", key=f"no_credits_cta_{st.session_state.get('page', '')}", use_container_width=True):
        st.session_state["page"] = "tarifs"
        st.rerun()


def get_search_count() -> int:
    if not is_logged_in():
        return 0
    profile = st.session_state.get("profile") or {}
    return int(profile.get("searches_used") or 0)


# ============================================================
# AUTHENTIFICATION
# ============================================================

def fetch_profile(user_id: str, access_token: str | None = None) -> dict | None:
    try:
        return supabase_select_profile(user_id, access_token)
    except Exception:
        return None


def ensure_profile_exists(user_id: str, email: str, access_token: str | None = None) -> dict:
    profile = fetch_profile(user_id, access_token)
    if profile:
        if profile.get("credits") is None:
            # Le trigger Supabase handle_new_user() a créé ce profil sans la
            # colonne 'credits' (migration SQL pas encore exécutée au moment
            # de l'inscription) : on répare immédiatement au lieu de laisser
            # le compte bloqué à 0 crédit. `is None` — jamais `not` — pour ne
            # jamais toucher un solde à 0 légitime (crédits déjà consommés).
            try:
                supabase_update_profile(
                    user_id,
                    {"credits": FREE_SIGNUP_CREDITS, "credits_gauge_max": FREE_SIGNUP_CREDITS},
                    access_token,
                )
                profile["credits"] = FREE_SIGNUP_CREDITS
                profile["credits_gauge_max"] = FREE_SIGNUP_CREDITS
            except Exception:
                pass
        return profile
    new_profile = {
        "id": user_id,
        "email": email,
        "searches_used": 0,
        "credits": FREE_SIGNUP_CREDITS,
        "credits_gauge_max": FREE_SIGNUP_CREDITS,
        "is_admin": email == ADMIN_EMAIL,
        "is_suspended": False,
    }
    try:
        supabase_insert_profile(new_profile, access_token)
    except Exception:
        pass
    return fetch_profile(user_id, access_token) or new_profile


@st.cache_data(show_spinner=False)
def load_disposable_domains() -> set[str]:
    """Charge la liste des domaines d'e-mails jetables depuis
    disposable_domains.txt (un domaine par ligne). Fichier absent = liste
    vide, ne bloque jamais une inscription légitime par erreur."""
    try:
        with open("disposable_domains.txt", "r", encoding="utf-8") as f:
            return {line.strip().lower() for line in f if line.strip() and not line.startswith("#")}
    except FileNotFoundError:
        return set()


def is_disposable_email(email: str) -> bool:
    domain = email.strip().lower().rsplit("@", 1)[-1] if "@" in email else ""
    return domain in load_disposable_domains()


def log_in(email: str, password: str, remember_me: bool) -> None:
    try:
        data = supabase_sign_in(email, password)
        user = data.get("user")
        access_token = data.get("access_token")
        if not user or not access_token:
            st.session_state["auth_error"] = "Identifiants incorrects. Merci de réessayer."
            return
        st.session_state["user"] = {
            "id": user["id"],
            "email": user["email"],
            "access_token": access_token,
        }
        st.session_state["profile"] = ensure_profile_exists(user["id"], user["email"], access_token)
        st.session_state["remember_me"] = remember_me
        st.session_state["auth_error"] = None
    except Exception as exc:
        st.session_state["auth_error"] = f"Connexion impossible : {exc}"


def sign_up(email: str, password: str) -> None:
    if is_disposable_email(email):
        st.session_state["auth_error"] = (
            "Les adresses e-mail jetables ne sont pas acceptées. "
            "Merci d'utiliser une adresse e-mail permanente."
        )
        return
    try:
        data = supabase_sign_up(email, password)
        # Selon que la confirmation par e-mail est activée sur le projet,
        # l'API renvoie soit {"user": {...}, "access_token": ...} (confirmation
        # désactivée), soit directement l'objet utilisateur à plat, sans
        # jeton (confirmation activée, en attente de clic sur le lien reçu).
        user = data.get("user") or (data if data.get("id") else None)
        if not user:
            st.session_state["auth_error"] = "Inscription impossible. Merci de réessayer."
            return
        access_token = data.get("access_token")
        ensure_profile_exists(user["id"], user["email"], access_token)
        st.session_state["auth_error"] = None
        if access_token:
            st.success("Compte créé ! Vous pouvez maintenant vous connecter.")
        else:
            st.success(
                "Compte créé ! Vérifie ta boîte mail (et tes spams) pour confirmer "
                "ton adresse avant de te connecter."
            )
    except Exception as exc:
        st.session_state["auth_error"] = f"Inscription impossible : {exc}"


def log_out() -> None:
    for key in ("user", "profile", "last_result", "remember_me"):
        st.session_state[key] = None
    st.session_state["page"] = "recherche"


def increment_search_count() -> None:
    """Compteur informatif (page Mon Compte / tableau de bord) — indépendant
    du solde de crédits, jamais limitant."""
    profile = st.session_state.get("profile") or {}
    user = st.session_state.get("user")
    new_count = get_search_count() + 1
    profile["searches_used"] = new_count
    st.session_state["profile"] = profile
    if user:
        try:
            supabase_update_profile(
                user["id"], {"searches_used": new_count}, user.get("access_token")
            )
        except Exception:
            pass


