def save_current_result_to_favorites() -> None:
    result = st.session_state.get("last_result")
    user = st.session_state.get("user")
    if not result or not user:
        return
    payload = {
        "user_id": user["id"],
        "title": result["titre"],
        "image_url": result["image_url"],
        "purchase_price": result["prix_produit"],
        "shipping_price": result["livraison"],
        "seller_score": result["fiabilite_score"],
        "potential_score": result["potentiel_score"],
        "payload": result,
    }
    try:
        headers = _auth_headers(user.get("access_token"))
        headers["Prefer"] = "return=minimal"
        requests.post(f"{REST_URL}/favoris", headers=headers, json=payload, timeout=10)
        st.success("Produit ajouté à tes favoris.")
    except Exception:
        st.warning("Impossible d'enregistrer ce favori pour le moment.")


def fetch_favorites(user: dict) -> list[dict]:
    try:
        response = requests.get(
            f"{REST_URL}/favoris",
            headers=_auth_headers(user.get("access_token")),
            params={"user_id": f"eq.{user['id']}", "select": "*", "order": "created_at.desc"},
            timeout=10,
        )
        return response.json() if response.status_code < 400 else []
    except Exception:
        return []


def delete_favorite(favorite_id, user: dict) -> None:
    try:
        requests.delete(
            f"{REST_URL}/favoris",
            headers=_auth_headers(user.get("access_token")),
            params={"id": f"eq.{favorite_id}", "user_id": f"eq.{user['id']}"},
            timeout=10,
        )
    except Exception:
        pass


def log_search_history(query: str, result_count: int, user: dict) -> None:
    try:
        headers = _auth_headers(user.get("access_token"))
        headers["Prefer"] = "return=minimal"
        requests.post(
            f"{REST_URL}/search_history",
            headers=headers,
            json={"user_id": user["id"], "query": query, "result_count": result_count},
            timeout=10,
        )
    except Exception:
        pass


def fetch_search_history(user: dict) -> list[dict]:
    try:
        response = requests.get(
            f"{REST_URL}/search_history",
            headers=_auth_headers(user.get("access_token")),
            params={"user_id": f"eq.{user['id']}", "select": "*", "order": "created_at.desc", "limit": "20"},
            timeout=10,
        )
        return response.json() if response.status_code < 400 else []
    except Exception:
        return []


def display_name(user: dict | None) -> str:
    """Prénom d'affichage dérivé de l'e-mail (aucune colonne 'nom' en base) :
    partie locale avant le premier '.', '+' ou '@', mise en forme."""
    email = (user or {}).get("email", "")
    local_part = email.split("@", 1)[0] if "@" in email else email
    first_token = re.split(r"[.+_-]", local_part)[0] if local_part else ""
    return first_token.capitalize() if first_token else "vous"


def get_dashboard_stats(user: dict) -> dict:
    """Statistiques réelles du tableau de bord — calculées à partir des
    favoris et de l'historique existants, jamais inventées : un compte
    tout neuf affiche donc naturellement des zéros partout."""
    favorites = fetch_favorites(user)
    history = fetch_search_history(user)
    today_str = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    searches_today = sum(1 for h in history if str(h.get("created_at", "")).startswith(today_str))
    margins = [
        fav["payload"]["marge_nette"]
        for fav in favorites
        if isinstance(fav.get("payload"), dict) and fav["payload"].get("marge_nette") is not None
    ]
    return {
        "searches_today": searches_today,
        "marge_moyenne": round(sum(margins) / len(margins), 2) if margins else 0.0,
        "produits_suivis": len(favorites),
        "economies_estimees": round(sum(margins), 2) if margins else 0.0,
        "recent_history": history[:4],
    }


def render_favorites_page() -> None:
    render_page_header("⭐ Favoris & Historique")
    user = st.session_state.get("user")
    if not user:
        return

    tab_favoris, tab_historique = st.tabs(["Favoris", "Historique de recherche"])

    with tab_favoris:
        favorites = fetch_favorites(user)
        if not favorites:
            st.caption("Aucun favori pour l'instant. Sauvegarde un produit depuis la page Recherche.")
        for fav in favorites:
            with st.container():
                col_img, col_info, col_action = st.columns([1, 3, 1])
                with col_img:
                    if fav.get("image_url"):
                        st.image(fav["image_url"], use_container_width=True)
                with col_info:
                    st.markdown(f"**{fav.get('title', 'Produit')}**")
                    st.caption(
                        f"Achat : {fav.get('purchase_price', 0):.2f} € · "
                        f"Fiabilité : {fav.get('seller_score', 0)} % · "
                        f"Potentiel : {fav.get('potential_score', 0)} / 100"
                    )
                with col_action:
                    if st.button("🗑️ Retirer", key=f"del_fav_{fav.get('id')}"):
                        delete_favorite(fav.get("id"), user)
                        st.rerun()
                st.divider()

    with tab_historique:
        history = fetch_search_history(user)
        if not history:
            st.caption("Aucune recherche enregistrée pour l'instant.")
        for h in history:
            st.markdown(f"🔍 **{h.get('query', '')}** — {h.get('created_at', '')[:10]}")


