# ============================================================
# AliExpress — GATEWAY TOP
# ============================================================

def _sign_top_params(params: dict, app_secret: str) -> str:
    """Signature MD5 requise par le Gateway TOP AliExpress (méthode 'md5')."""
    sorted_items = sorted(params.items())
    base_string = app_secret + "".join(f"{k}{v}" for k, v in sorted_items) + app_secret
    return hashlib.md5(base_string.encode("utf-8")).hexdigest().upper()


def call_aliexpress_gateway(method: str, extra_params: dict) -> dict | None:
    """
    Appelle le Gateway TOP AliExpress. Nécessite ALIEXPRESS_APP_SECRET
    dans .streamlit/secrets.toml (non fourni par le AppKey seul).
    Les méthodes "aliexpress.ds.*" nécessitent en plus un jeton d'accès
    OAuth (paramètre "session"), obtenu via handle_aliexpress_oauth_return.
    Retourne None si l'appel échoue, pour permettre un repli propre.
    L'erreur exacte est conservée dans st.session_state pour diagnostic.
    """
    if not ALIEXPRESS_APP_SECRET:
        st.session_state["last_aliexpress_error"] = "ALIEXPRESS_APP_SECRET vide."
        return None

    params = {
        "method": method,
        "app_key": ALIEXPRESS_APP_KEY,
        "timestamp": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "format": "json",
        "v": "2.0",
        "sign_method": "md5",
        **extra_params,
    }
    access_token = get_app_config("aliexpress_access_token")
    if access_token:
        params["session"] = access_token
    params["sign"] = _sign_top_params(params, ALIEXPRESS_APP_SECRET)

    try:
        response = requests.get(ALIEXPRESS_GATEWAY, params=params, timeout=15)
        response.raise_for_status()
        data = response.json()
        st.session_state["last_aliexpress_error"] = None
        st.session_state["last_aliexpress_raw"] = data
        return data
    except Exception as exc:
        st.session_state["last_aliexpress_error"] = f"{type(exc).__name__}: {exc}"
        return None


def search_product(query: str) -> dict:
    """
    Recherche un produit sur AliExpress via le Gateway TOP (API Drop
    Shipping, aliexpress.ds.*). Nécessite un App Secret ET une
    autorisation OAuth valide (voir handle_aliexpress_oauth_return).
    En l'absence de l'un ou l'autre (ou en cas d'échec réseau), une
    estimation de démonstration est générée pour ne jamais bloquer l'UI.
    """
    api_result = call_aliexpress_gateway(
        "aliexpress.ds.text.search",
        {"keyWord": query, "pageSize": "1", "pageIndex": "1", "local": "fr_FR"},
    )

    if api_result:
        # Squelette d'extraction — le nom exact des champs de réponse pour
        # cette méthode n'est pas documenté publiquement de façon fiable ;
        # à ajuster une fois qu'on voit la vraie réponse via le diagnostic.
        return _parse_aliexpress_payload(api_result, query)

    return _generate_demo_estimate(query)


def _parse_aliexpress_payload(payload: dict, query: str) -> dict:
    # Squelette d'extraction — à ajuster une fois qu'on voit la vraie
    # structure JSON renvoyée par aliexpress.ds.text.search (visible dans
    # le diagnostic admin après un appel réussi).
    try:
        response_root = next(
            (v for k, v in payload.items() if k.endswith("_response")), payload
        )
        item = response_root["data"]["products"][0]
        base_price = float(item.get("target_sale_price", 0)) or 8.5
        shipping = 2.0
        image_url = item.get("product_main_image_url", "")
        product_url = item.get("product_detail_url", "")
        vendor_rating = float(str(item.get("evaluate_rate", "92")).replace("%", "")) / 100
        orders = int(item.get("volume", 500))
        title = item.get("product_title", query)
        return _build_result(
            title, base_price, shipping, image_url, vendor_rating, orders, query, product_url
        )
    except Exception:
        return _generate_demo_estimate(query)


def _generate_demo_estimate(query: str) -> dict:
    """Estimation déterministe (mode démo) tant que l'App Secret n'est pas configuré."""
    seed = int(hashlib.sha256(query.encode("utf-8")).hexdigest(), 16) % (10**6)
    rng = random.Random(seed)
    base_price = round(rng.uniform(3.5, 24.0), 2)
    shipping = round(rng.uniform(0.0, 4.5), 2)
    vendor_rating = round(rng.uniform(0.80, 0.99), 2)
    orders = rng.randint(80, 12000)
    image_url = "https://placehold.co/400x400/0F1117/38BDF8?text=MargeMax"
    # En mode démo, aucune vraie fiche produit n'existe : on ne fabrique pas
    # de fausse URL AliExpress. product_url reste vide, et l'interface bascule
    # alors vers le lien de recherche générale AliExpress.
    return _build_result(
        query.title(), base_price, shipping, image_url, vendor_rating, orders, query, ""
    )


def _build_result(
    title: str,
    base_price: float,
    shipping: float,
    image_url: str,
    vendor_rating: float,
    orders: int,
    query: str,
    product_url: str = "",
) -> dict:
    cout_total = round((base_price + shipping) * (1 + VAT_RATE), 2)
    prix_conseille = math.floor(cout_total / MARGIN_TARGET) + 0.99
    frais_paiement = round(prix_conseille * PAYMENT_FEE_RATE, 2)
    marge_nette = round(prix_conseille - cout_total - frais_paiement, 2)

    fiabilite_score = round(min(99, max(35, vendor_rating * 100 - (0 if orders > 300 else 15))))
    potentiel_score = round(min(99, max(20, 55 + (vendor_rating - 0.85) * 200 + (orders / 500))))

    canaux = []
    if potentiel_score >= 70:
        canaux.append("TikTok Ads")
    if base_price <= 15:
        canaux.append("Shopify")
    if base_price <= 8:
        canaux.append("Vinted")
    if not canaux:
        canaux.append("Shopify")

    return {
        "titre": title,
        "requete": query,
        "image_url": image_url,
        "product_url": product_url,
        "prix_produit": base_price,
        "livraison": shipping,
        "cout_total": cout_total,
        "prix_conseille": round(prix_conseille, 2),
        "frais_paiement": frais_paiement,
        "marge_nette": marge_nette,
        "fiabilite_score": fiabilite_score,
        "note_produit": round(vendor_rating * 5, 1),
        "commandes": orders,
        "note_vendeur": round(vendor_rating * 5, 1),
        "potentiel_score": potentiel_score,
        "delai_livraison": "12-20 jours" if shipping < 3 else "7-15 jours",
        "canaux": canaux,
    }


